window.VIBE_LESSONS=[{"title": "Dall’idea al primo quiz interattivo", "intro": "Trasforma un bisogno di apprendimento in un piccolo quiz. Imparerai a specificare il risultato, generare una prima versione, provarla e migliorarla.", "product": "Un quiz di tre domande con feedback, punteggio e riavvio.", "goals": ["Distinguere un obiettivo didattico da una funzione dell’app.", "Scrivere un prompt con destinatari, obiettivo e vincoli.", "Provare il prototipo prima di usarlo."], "example": {"kind": "Quiz interattivo", "audience": "Studenti di seconda liceo", "goal": "Distinguere fonti storiche primarie e secondarie", "features": "Tre domande con una sola risposta corretta, spiegazione dopo la risposta, punteggio e riavvio"}, "steps": [{"title": "1. Scegli che cosa vuoi far imparare", "explain": "Parti dal bisogno di apprendimento e descrivi un’attività osservabile. «Un’app di storia» lascia molte decisioni al modello; «classificare tre fonti e motivare la scelta» permette di definire funzioni e prove. La sezione iniziale chiarisce che cosa intendiamo per vibe coding e come useremo la verifica nel corso.", "prompt": "Aiutami a definire un’attività per [destinatari] su [argomento]. L’obiettivo è [azione osservabile]. Proponi una sola funzione principale e tre criteri con cui verificare se serve all’obiettivo. Non scrivere ancora il codice.", "action": "Completa: «L’utente deve imparare a…; l’app gli permette di…».", "check": "L’obiettivo descrive un apprendimento; la funzione descrive un’azione nell’app."}, {"title": "2. Scrivi una richiesta verificabile", "explain": "Specifica destinatari, obiettivo, funzioni e vincoli. Usa contenuti dimostrativi e non dati reali degli studenti.", "prompt": "Crea un quiz per [destinatari] sull’obiettivo [obiettivo]. Deve avere tre domande, quattro opzioni e una sola risposta corretta per domanda, spiegazione dopo la risposta, punteggio e riavvio. Prima descrivi il comportamento e i criteri di verifica. Non aggiungere login o raccolta dati.", "action": "Sostituisci tutti i campi tra parentesi e controlla che le funzioni siano numerabili.", "check": "Per ogni funzione sai dire quale risultato ti aspetti."}, {"title": "3. Chiedi la prima versione e aprila", "explain": "HTML organizza i contenuti, CSS ne definisce l’aspetto e JavaScript gestisce le interazioni. Per iniziare puoi richiedere tutto in un singolo file.", "prompt": "Usa la specifica concordata per generare un unico file HTML completo con CSS e JavaScript incorporati, adatto a smartphone e computer. Spiega come salvarlo come quiz.html e aprirlo nel browser. Usa dati fittizi e nessuna dipendenza esterna. Distingui il codice generato dai test realmente eseguiti.", "action": "Salva il file con estensione .html e aprilo nel browser.", "check": "Vedi tre domande e puoi scegliere una risposta senza installare altri strumenti."}, {"title": "4. Prova prima di fidarti", "explain": "Una pagina che si apre non è ancora un quiz verificato. Controlla sia le risposte disciplinari sia punteggio e riavvio.", "prompt": "Proponi cinque test riproducibili per il quiz: risposta corretta, risposta errata, tentativo di invio senza scelta, punteggio finale e riavvio. Per ciascuno indica azione e risultato atteso. Non dichiarare di averli eseguiti.", "action": "Esegui i test e annota risultato atteso, osservato ed esito.", "check": "Controlli il punteggio anche dopo una risposta errata e dopo il riavvio."}, {"title": "5. Migliora un aspetto e riprova", "explain": "Una modifica circoscritta permette di capire che cosa è cambiato. Dopo una correzione ripeti anche i test precedenti.", "prompt": "Aggiungi una spiegazione disciplinare dopo ogni risposta, senza cambiare domande, punteggio o riavvio. Indica quali parti modifichi e quali test devo ripetere. Se trovi dati mancanti, chiedimeli.", "action": "Confronta prima e dopo. Conserva il file, il prompt iniziale e il registro dei test.", "check": "Sai distinguere ciò che hai deciso, ciò che l’IA ha generato e ciò che hai effettivamente verificato."}], "quiz": [{"case": "Vuoi un’app per aiutare una classe a distinguere fonti primarie e secondarie. Qual è il primo passo?", "options": ["Definire l’azione di apprendimento e una funzione che la eserciti.", "Scegliere le animazioni.", "Aggiungere login e chat.", "Generare un sito prima di scegliere il contenuto."], "correct": 0, "feedback": "Un obiettivo osservabile guida la progettazione e permette di verificare l’utilità del quiz.", "hint": "Confronta un’azione di apprendimento con una scelta puramente grafica."}, {"case": "Il prompt «Fammi un’app bella» dà risultati imprevedibili. Come lo migliori?", "options": ["Chiedendo solo uno stile moderno.", "Indicando destinatari, obiettivo, tre domande, feedback e riavvio.", "Lasciando all’IA ogni decisione didattica.", "Chiedendo più funzioni senza elencarle."], "correct": 1, "feedback": "Destinatari e funzioni esplicite rendono il risultato confrontabile con la richiesta.", "hint": "Chiediti quali dettagli consentono di verificare il risultato dell’IA."}, {"case": "Il quiz generato si apre nel browser. Che cosa fai prima di usarlo?", "options": ["Lo distribuisci subito.", "Controlli solo il titolo.", "Provi risposte, contenuti, punteggio e riavvio.", "Aggiungi altre domande senza controllare le prime."], "correct": 2, "feedback": "L’apertura della pagina non dimostra la correttezza delle interazioni o delle risposte.", "hint": "Distingui l’apertura di una pagina dalla verifica delle sue funzioni."}, {"case": "Vuoi aggiungere spiegazioni al quiz già funzionante. Quale richiesta è più controllabile?", "options": ["Riscrivi tutta l’app.", "Cambia grafica e contenuti insieme.", "Rendi il risultato perfetto.", "Aggiungi spiegazioni preservando domande, punteggio e riavvio."], "correct": 3, "feedback": "Una modifica limitata rende più facile isolare gli effetti e ripetere i test.", "hint": "Pensa a come isolare l’effetto di una sola modifica."}, {"case": "Il quiz assegna un punto a una risposta sbagliata. Come chiedi aiuto all’IA?", "options": ["Descrivi passaggi, atteso e osservato e chiedi una correzione circoscritta.", "Chiedi un colore diverso.", "Ignori l’errore se è raro.", "Elimini ogni feedback."], "correct": 0, "feedback": "Un caso riproducibile aiuta a diagnosticare e verificare il difetto.", "hint": "Una buona segnalazione permette a un’altra persona di riprodurre il difetto."}, {"case": "Due colleghi incollano lo stesso prompt e ottengono due quiz diversi. Come lo interpreti?", "options": ["Uno dei due ha sbagliato a copiare il prompt.", "Il modello genera testo in modo probabilistico: le versioni vanno provate con gli stessi test.", "L’IA sceglie sempre la versione migliore, quindi sono equivalenti.", "Basta ripetere il prompt finché le due versioni non coincidono."], "correct": 1, "feedback": "La variabilità è normale: ciò che rende confrontabili le versioni sono i criteri e i test che hai definito.", "hint": "Pensa a come un modello linguistico produce la risposta e a che cosa resta costante tra due versioni."}, {"case": "Gli studenti useranno in classe il quiz HTML generato. Durante l’uso, che cosa succede alle loro risposte?", "options": ["Vengono inviate al modello che ha generato il quiz.", "Sono salvate nell’account del docente.", "Se il codice non prevede invii o servizi esterni, sono elaborate solo nel browser.", "Sono pubblicate automaticamente su GitHub."], "correct": 2, "feedback": "L’IA serve a costruire il file; un quiz autonomo non la usa durante l’esecuzione. Va comunque verificato che il codice non invii dati.", "hint": "Distingui il momento in cui l’IA genera il codice dal momento in cui il browser lo esegue."}, {"case": "Per la demo hai un elenco con nomi e voti reali. Quali dati inserisci nel prompt?", "options": ["L’intero elenco.", "I dati e la password del registro.", "Nomi reali con voti inventati.", "Dati completamente fittizi sufficienti a provare l’app."], "correct": 3, "feedback": "La prova del prototipo non richiede dati identificativi reali.", "hint": "Chiediti quali informazioni sono davvero necessarie per una dimostrazione."}, {"case": "Il punteggio funziona, ma un’opera è attribuita all’autore sbagliato. Come procedi?", "options": ["Correggi il contenuto e riprovi il quiz.", "Accetti l’errore perché il software funziona.", "Cambi solo il titolo.", "Attribuisci ogni responsabilità all’IA."], "correct": 0, "feedback": "La correttezza disciplinare va verificata oltre a quella tecnica.", "hint": "Distingui la correttezza del software dalla correttezza dei contenuti."}, {"case": "Devi documentare il prototipo. Quale resoconto è più utile?", "options": ["Solo uno screenshot.", "Obiettivo, prompt, modifica, test con esiti e limiti residui.", "Una dichiarazione di perfezione.", "Il numero di colori usati."], "correct": 1, "feedback": "Le evidenze distinguono il lavoro generato da quello effettivamente verificato.", "hint": "Cerca evidenze che permettano a un’altra persona di ripetere le prove."}], "id": 1, "version": 2, "concepts": [{"title": "Che cosa significa vibe coding", "text": "Il termine indica un modo di costruire prototipi dialogando con un modello che genera codice. Nella sua accezione originaria si delega anche molta lettura del codice. In questo corso usiamo la prototipazione come punto di partenza e la completiamo con comprensione, revisione e test prima dell’uso in classe. La distinzione è discussa da Simon Willison [1]."}, {"title": "Come funziona il dialogo", "text": "Il modello produce codice a partire dalle istruzioni e dal contesto della conversazione. Può introdurre errori o ipotesi non richieste. Il browser esegue il codice; tu osservi il comportamento e descrivi la differenza rispetto all’atteso. Due generazioni dello stesso prompt possono dare risultati diversi."}, {"title": "Che cosa resta nelle tue mani", "text": "Scegli obiettivo, esempi e criteri di correttezza. L’IA propone un’implementazione. Chiedile di spiegare input, regole e output; verifica la spiegazione e fai riesaminare le parti che non comprendi. Un quiz a correzione fissa può funzionare dopo la generazione senza usare un’IA durante l’esecuzione."}], "disciplineExamples": [{"area": "Italiano", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere similitudine e metafora in sei brevi esempi originali controllati dal docente", "features": "Scelte, motivazione dopo la risposta e riavvio", "evidence": "Classifica un nuovo esempio e motiva la scelta.", "case": {"probe": "Classifica e motiva: «Il tuo sorriso è una finestra aperta sul mattino».", "full": "«È una metafora: il sorriso è paragonato a una finestra senza parole di paragone come “come” o “simile a”.»", "partial": "«È una metafora, perché è una figura poetica.»", "why": "L’etichetta è giusta ma il criterio manca: “figura poetica” vale anche per la similitudine. Potrebbe aver indovinato."}}, {"area": "Storia e filosofia", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Distinguere fonti primarie e secondarie in esempi con contesto dichiarato", "features": "Tre fonti predisposte dal docente, scelta, motivazione e riavvio", "evidence": "Classifica una fonte nuova rispetto al quesito storico indicato.", "case": {"probe": "Quesito: come vivevano i soldati in trincea nel 1916? Fonte: lettera di un fante alla famiglia, scritta dal fronte nel 1916.", "full": "«È primaria: l’ha scritta un testimone diretto nel periodo studiato e risponde al quesito con la sua esperienza.»", "partial": "«È primaria perché è una lettera.»", "why": "Il tipo di documento non decide: una lettera scritta oggi da uno storico sarebbe secondaria. Il criterio è il rapporto tra fonte, evento e quesito."}}, {"area": "Lingue straniere", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Scegliere tempi verbali adeguati in situazioni comunicative B1", "features": "Frasi originali, contesto sufficiente, una scelta univoca e motivazione", "evidence": "Scegli la forma in un nuovo contesto e spiega l’indizio temporale.", "case": {"probe": "Completa: «I ___ (live) in Rome since 2019».", "full": "«have lived (o have been living): l’azione è iniziata nel passato e continua ora; l’indizio è since.»", "partial": "«lived, perché il 2019 è passato.»", "why": "Coglie il riferimento al passato ma non il legame con il presente segnalato da since: è l’errore tipico di chi traduce dall’italiano «vivo a Roma dal 2019»."}}, {"area": "Matematica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Confrontare frazioni con denominatori positivi", "features": "Tre casi, spiegazione del confronto, punteggio e riavvio", "evidence": "Ordina una nuova coppia e spiega il criterio.", "case": {"probe": "Ordina 3/4 e 5/7.", "full": "«3/4 > 5/7: con denominatore comune 28 ottengo 21/28 e 20/28, quindi vince 3/4.»", "partial": "«5/7 è più grande perché 5 e 7 sono più grandi di 3 e 4.»", "why": "Confronta numeratori e denominatori come numeri separati: è l’errore tipico che il quiz deve far emergere."}}, {"area": "Scienze e fisica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Distinguere osservazione, ipotesi e conclusione in casi sperimentali brevi", "features": "Casi originali verificati, scelta e motivazione", "evidence": "Classifica una nuova frase e spiega la decisione.", "case": {"probe": "Classifica: «Le piantine tenute al buio sono diventate gialle e più alte di quelle alla luce».", "full": "«È un’osservazione: descrive ciò che si è visto e misurato, senza spiegarne la causa.»", "partial": "«È una conclusione, perché dice com’è andato l’esperimento.»", "why": "Confonde il risultato osservato con la sua interpretazione: una conclusione direbbe perché le piantine sono cambiate."}}, {"area": "Arte e musica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere elementi formali in esempi descritti o materiali autorizzati", "features": "Schede validate dal docente, una scelta univoca e motivazione", "evidence": "Indica un elemento formale in un esempio nuovo.", "case": {"probe": "In un dipinto le linee del pavimento e del soffitto convergono in un unico punto al centro, dietro la figura principale. Quale elemento formale riconosci?", "full": "«La prospettiva lineare centrale: le linee in profondità convergono nel punto di fuga, che qui guida lo sguardo verso la figura.»", "partial": "«La profondità, perché sembra tridimensionale.»", "why": "Descrive l’effetto ma non nomina l’elemento formale né l’indizio visibile che lo rivela."}}, {"area": "Informatica", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere input, elaborazione e output in piccoli programmi", "features": "Tre casi, traccia e feedback che spiega la sequenza", "evidence": "Ricostruisci l’output di un caso nuovo.", "case": {"probe": "a = 4\nb = a * 2\nprint(a + b)\nQuale output?", "full": "«12. Input: a vale 4; elaborazione: b diventa 8, poi si calcola a + b; output: 12.»", "partial": "«8.»", "why": "Si ferma all’ultima assegnazione e confonde il valore di b con ciò che viene stampato: non segue la sequenza fino all’output."}}, {"area": "Diritto ed economia", "kind": "Quiz interattivo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Collocare una norma nella gerarchia delle fonti del diritto", "features": "Tre norme descritte dal docente (Costituzione, legge, regolamento), una scelta univoca e motivazione", "evidence": "Colloca una norma nuova nella gerarchia e motiva la scelta.", "case": {"probe": "Il Governo, in un caso straordinario di necessità e urgenza, adotta un decreto-legge. Dove lo collochi?", "full": "«Tra le fonti primarie, allo stesso livello della legge ordinaria. Ha forza di legge (art. 77 Cost.), quindi sta sotto la Costituzione e sopra i regolamenti.»", "partial": "«Sotto la Costituzione», senza spiegare perché; oppure «sotto la legge, perché lo fa il Governo».", "why": "La seconda risposta mostra un errore tipico: confondere chi emana l’atto con la forza che l’atto ha."}}], "promptContrast": {"weak": "Fammi un quiz bello.", "reason": "Mancano destinatari, obiettivo, contenuti controllati e comportamento da verificare."}, "schedule": "20 min · Che cos’è il vibe coding e come funziona (guida al corso) · 30 min · confronto tra prompt vago e prompt specifico · 70 min · laboratorio: primo quiz nella propria disciplina · 10 min pausa · 35 min · test incrociati tra colleghi · 35 min · progettazione dell’attività in classe (modalità A) · 10 min pausa · 30 min · test finale e domande aperte.", "classroom": {"mode": "A", "modeLabel": "Modalità A · Il docente costruisce, la classe usa", "title": "Il quiz «con un errore nascosto»", "intro": "Gli studenti non usano l’IA e non hanno bisogno di account: usano il quiz che hai generato e verificato. L’attività rende visibile ai ragazzi ciò che hai imparato oggi: un prodotto che funziona non è per questo corretto.", "steps": [["5 min · Previsione", "Presenta il quiz e chiedi di prevedere quale domanda sarà la più difficile e perché."], ["10 min · Uso", "Le coppie svolgono il quiz. Uno risponde, l’altro annota i dubbi su domande e spiegazioni."], ["10 min · Caccia all’errore", "Rivela che una spiegazione contiene un’imprecisione voluta, scelta da te: le coppie la cercano e la correggono motivando."], ["5 min · Riflessione", "Raccogli una correzione per coppia e chiedi: chi è responsabile del contenuto di un’app generata con l’IA?"]], "assess": "Valuta la correttezza disciplinare delle correzioni e la qualità della motivazione, non la velocità nel quiz."}}, {"title": "Progettare una lezione interattiva", "intro": "Costruisci una lezione digitale che accompagni chi studia: spiegazione breve, esempio, esercizio e feedback. Trasforma il percorso in requisiti prima di chiedere il codice.", "product": "Una lezione web con quattro passaggi, esercizio e feedback motivato.", "goals": ["Scomporre un percorso in passaggi progressivi.", "Definire azioni e criteri di accettazione.", "Costruire prompt coerenti tra contenuti e interfaccia."], "example": {"kind": "Lezione interattiva", "audience": "Studenti di prima liceo", "goal": "Confrontare due frazioni con denominatore diverso", "features": "Spiegazione breve, esempio svolto, esercizio autonomo, feedback motivato e navigazione avanti e indietro"}, "steps": [{"title": "1. Definisci risultato e prerequisiti", "explain": "Una lezione efficace non è un lungo testo su schermo. Parti da ciò che l’utente sa già e da ciò che deve saper fare alla fine.", "prompt": "Progetta una lezione su [argomento] per [destinatari]. Prerequisiti: [conoscenze]. Risultato osservabile: [azione]. Proponi quattro passaggi: spiegazione breve, esempio svolto, esercizio, feedback. Non scrivere ancora codice.", "action": "Scrivi un obiettivo e due prerequisiti.", "check": "Ogni passaggio prepara il successivo senza richiedere conoscenze non dichiarate."}, {"title": "2. Descrivi il percorso dell’utente", "explain": "Chiarisci cosa vede l’utente, cosa fa e cosa succede dopo. Il flusso deve prevedere anche errori e ritorni.", "prompt": "Per i quattro passaggi concordati descrivi: contenuto visibile, azione dell’utente, risposta del sistema e navigazione. Prevedi una risposta errata e la possibilità di tornare all’esempio senza perdere l’esercizio.", "action": "Disegna su carta le quattro schermate e collegale con frecce.", "check": "Non esistono pulsanti senza un comportamento definito."}, {"title": "3. Formula criteri di accettazione", "explain": "«Deve essere intuitiva» non basta. Un criterio utile si può provare, per esempio controllando il mantenimento della risposta dopo un ritorno.", "prompt": "Trasforma i requisiti in una tabella con requisito, prova e risultato atteso. Includi feedback motivato, ritorno all’esempio, ripresa dell’esercizio e uso da tastiera. Se un requisito è ambiguo, proponi una formulazione verificabile.", "action": "Scegli quattro criteri indispensabili e rimanda le funzioni opzionali.", "check": "Un’altra persona può ripetere le prove senza chiederti che cosa intendevi."}, {"title": "4. Genera una prima versione essenziale", "explain": "Chiedi al modello di usare la specifica e di non cambiare l’obiettivo durante lo sviluppo.", "prompt": "Genera la lezione concordata in un unico file HTML con CSS e JavaScript. Mantieni testi brevi, pulsanti con etichette esplicite e input etichettati. Non aggiungere account, classifiche o tracciamento. Fornisci istruzioni di apertura e piano di test.", "action": "Apri la lezione come se fossi un nuovo utente e percorri tutte le schermate.", "check": "Il flusso è completo anche quando sbagli l’esercizio."}, {"title": "5. Rivedi il feedback con una modifica mirata", "explain": "Il feedback deve aiutare a capire l’errore, senza limitarsi a mostrare «sbagliato».", "prompt": "Quando la risposta all’esercizio è errata, aggiungi un suggerimento che richiami il passaggio pertinente dell’esempio, senza svelare subito il risultato. Mantieni invariati navigazione e stato dell’esercizio. Elenca i test di regressione.", "action": "Prova risposta corretta, errata e ritorno all’esempio.", "check": "Il suggerimento è coerente con l’errore e le risposte restano conservate durante la navigazione."}], "quiz": [{"case": "Devi trasformare una spiegazione sulle frazioni in una lezione web. Da che cosa parti?", "options": ["Da una classifica degli utenti.", "Da prerequisiti e azione che lo studente dovrà saper compiere.", "Da un testo il più lungo possibile.", "Dalla scelta di un database."], "correct": 1, "feedback": "Prerequisiti e obiettivo permettono di dosare i passaggi e scegliere gli esercizi.", "hint": "Pensa a ciò che l’utente sa prima e deve saper fare dopo."}, {"case": "Il prompt chiede «una lezione interattiva» ma l’IA produce solo testo. Che cosa mancava?", "options": ["Un aggettivo più entusiasta.", "La richiesta di più colori.", "Le azioni dell’utente e le risposte attese del sistema.", "Il nome del computer."], "correct": 2, "feedback": "L’interazione va descritta come azione e conseguenza, non solo nominata.", "hint": "Il termine «interattivo» da solo non descrive un comportamento."}, {"case": "Hai spiegazione, esempio ed esercizio. Quale sequenza sostiene un percorso progressivo?", "options": ["Esercizio senza contesto, classifica e uscita.", "Feedback prima della domanda.", "Tutte le schermate sovrapposte.", "Spiegazione breve, esempio svolto, esercizio e feedback."], "correct": 3, "feedback": "La sequenza fornisce un modello prima di chiedere un’applicazione autonoma.", "hint": "Considera quale supporto serve prima di un tentativo autonomo."}, {"case": "Scrivi «la navigazione deve essere intuitiva». Quale criterio lo rende verificabile?", "options": ["Da ogni esercizio si torna all’esempio e poi si riprende senza perdere la risposta.", "La navigazione deve piacere a tutti.", "La grafica deve essere innovativa.", "Il codice deve essere molto lungo."], "correct": 0, "feedback": "Il comportamento osservabile permette una prova ripetibile.", "hint": "Un criterio utile deve poter essere osservato con una prova."}, {"case": "Una risposta errata produce soltanto «No». Come migliori la specifica?", "options": ["Nascondi l’esercizio dopo l’errore.", "Richiedi un suggerimento legato al passaggio sbagliato.", "Aggiungi un suono senza altre indicazioni.", "Mostri sempre la risposta finale prima del tentativo."], "correct": 1, "feedback": "Un feedback mirato aiuta a rivedere il ragionamento senza sostituirlo.", "hint": "Chiediti che cosa aiuta l’utente a rivedere il proprio ragionamento."}, {"case": "L’utente torna all’esempio e perde tutte le risposte. Che cosa devi precisare?", "options": ["Una nuova palette.", "Un titolo più breve.", "Quale stato conservare e quando azzerarlo.", "Una classifica obbligatoria."], "correct": 2, "feedback": "La gestione dello stato fa parte del flusso e deve essere esplicitata e provata.", "hint": "Descrivi cosa deve accadere ai dati durante avanti e indietro."}, {"case": "L’IA propone login e chat, ma l’obiettivo è una lezione di quattro passaggi. Come procedi?", "options": ["Accetti tutte le aggiunte.", "Rinunci all’obiettivo.", "Costruisci prima la chat.", "Mantieni le funzioni essenziali e rinvii quelle non necessarie."], "correct": 3, "feedback": "Il perimetro minimo protegge il tempo e la coerenza con l’obiettivo.", "hint": "Confronta ciascuna funzione proposta con l’obiettivo essenziale."}, {"case": "Vuoi verificare l’uso da tastiera. Quale prova esegui?", "options": ["Usi Tab e i tasti di attivazione controllando ordine, focus e pulsanti.", "Riduci solo la luminosità.", "Usi soltanto il mouse.", "Controlli il nome del file."], "correct": 0, "feedback": "La prova deve riprodurre la modalità d’uso richiesta, compresa la visibilità del focus.", "hint": "La prova deve usare la stessa modalità d’interazione che vuoi verificare."}, {"case": "Dopo l’aggiunta di un indizio il pulsante Indietro smette di funzionare. Quale controllo era necessario?", "options": ["Solo il testo dell’indizio.", "Ripetere anche i test della navigazione.", "Solo l’immagine iniziale.", "Nessun controllo dopo una piccola modifica."], "correct": 1, "feedback": "Una modifica al feedback richiede anche test delle funzioni già presenti.", "hint": "Considera possibili effetti collaterali della modifica."}, {"case": "La lezione richiede operazioni che gli utenti non conoscono. Quale revisione è pertinente?", "options": ["Aggiungere animazioni.", "Nascondere i prerequisiti.", "Introdurre il passaggio mancante o adeguare attività e destinatari.", "Aumentare solo la velocità delle transizioni."], "correct": 2, "feedback": "La progressione deve essere compatibile con le conoscenze iniziali dichiarate.", "hint": "Controlla il rapporto tra difficoltà dell’esercizio e conoscenze iniziali."}], "id": 2, "version": 2, "concepts": [{"title": "Dal contenuto all’attività", "text": "Un contenuto espone informazioni; un’attività chiede una decisione o una produzione osservabile. Prima di aggiungere pulsanti, specifica che cosa farà lo studente e quale evidenza mostrerà la comprensione."}, {"title": "Il prompt come specifica", "text": "Una buona richiesta contiene destinatari, prerequisiti, obiettivo, azioni, feedback e criteri di accettazione. Scrivere questi elementi chiarisce la progettazione. Il prompt può essere rivisto dopo una prova."}, {"title": "Feedback e autonomia", "text": "Un indizio deve aiutare a riprendere il ragionamento. Prevedi sostegni iniziali e una prova finale con meno aiuti. Per risposte interpretative usa criteri espliciti e revisione umana, evitando una correzione automatica basata solo su parole chiave."}], "disciplineExamples": [{"area": "Italiano", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere tesi, argomento ed esempio in un testo breve fornito dal docente", "features": "Spiegazione, testo annotato, selezione di segmenti e feedback guidato", "evidence": "Individua una tesi in un testo nuovo e giustifica il confine del segmento.", "case": {"probe": "Testo: «La biblioteca di quartiere dovrebbe restare aperta la sera. Molti studenti lavorano di giorno e non hanno altro momento per studiare. Marta, per esempio, ci va dopo il turno al bar». Individua tesi, argomento ed esempio.", "full": "«Tesi: la prima frase. Argomento: molti studenti lavorano di giorno, ed è la ragione che sostiene la tesi. Esempio: il caso di Marta, che illustra l’argomento ma da solo non lo dimostra.»", "partial": "«La tesi è che Marta va in biblioteca dopo il turno.»", "why": "Scambia l’esempio, più concreto e facile da ricordare, per la tesi: non distingue il caso particolare dall’affermazione generale."}}, {"area": "Storia e filosofia", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Distinguere una tesi dalle ragioni che la sostengono", "features": "Esempio annotato, decisione, suggerimento e breve giustificazione", "evidence": "Ricostruisci tesi e ragione di un argomento nuovo.", "case": {"probe": "«Dovremmo dubitare delle nostre opinioni, perché molte convinzioni che sembravano certe si sono rivelate false». Ricostruisci tesi e ragione.", "full": "«Tesi: dovremmo dubitare delle nostre opinioni. Ragione: molte convinzioni ritenute certe si sono rivelate false. Il “perché” segnala il passaggio dalla tesi alla ragione.»", "partial": "«La tesi è che le nostre convinzioni sono false.»", "why": "Prende la ragione per la tesi e la generalizza: «molte si sono rivelate false» diventa «sono false»."}}, {"area": "Lingue straniere", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Formulare richieste cortesi in un dialogo B1", "features": "Esempio, scelta guidata, riformulazione e feedback con alternative ammissibili", "evidence": "Riformula una richiesta nuova in modo adeguato al contesto.", "case": {"probe": "Sei all’ufficio informazioni di una stazione a Londra e vuoi una mappa della città. Formula la richiesta.", "full": "«Could I have a map of the city, please?» oppure «Would you mind giving me a map?»: domanda con un modale e formula di cortesia, adatta a uno sconosciuto.", "partial": "«Give me a map, please.»", "why": "È corretta grammaticalmente, ma l’imperativo resta brusco anche con please: il registro non è adatto al contesto."}}, {"area": "Matematica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Sommare due frazioni con denominatori diversi", "features": "Esempio svolto, passaggi progressivi, esercizio e indizio", "evidence": "Risolvi una somma nuova senza l’esempio svolto.", "case": {"probe": "Calcola 2/3 + 1/4 senza guardare l’esempio svolto.", "full": "«Il minimo comune multiplo è 12: 8/12 + 3/12 = 11/12.»", "partial": "«3/7.»", "why": "Somma numeratori e denominatori tra loro: è l’errore che l’esercizio guidato doveva prevenire."}}, {"area": "Scienze e fisica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Leggere variabili e controlli in un esperimento semplice", "features": "Scenario, esempio, identificazione delle variabili e feedback", "evidence": "Indica variabile indipendente e controllo in un esperimento nuovo.", "case": {"probe": "Uno studente misura in quanto tempo si scioglie lo zucchero in acqua a 20, 40 e 60 °C, usando sempre 10 g di zucchero e 200 ml d’acqua, senza mescolare. Indica variabili e controlli.", "full": "«Variabile indipendente: la temperatura, perché è quella che cambio. Dipendente: il tempo di scioglimento. Controllate: massa di zucchero, volume d’acqua, nessun mescolamento.»", "partial": "«La variabile indipendente è il tempo, perché lo misura.»", "why": "Confonde la variabile misurata con quella modificata dallo sperimentatore."}}, {"area": "Arte e musica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Analizzare composizione, ritmo o struttura con una griglia", "features": "Esempio annotato, osservazione guidata e breve analisi personale", "evidence": "Applica la griglia a un’opera o brano diverso con materiali utilizzabili.", "case": {"probe": "Applica la griglia al tema dell’«Inno alla gioia» dal finale della Nona sinfonia di Beethoven, nella versione semplice per flauto: quante frasi, quali si ripetono?", "full": "«Quattro frasi della stessa lunghezza: A, A′ (come A ma con finale conclusivo), B (contrastante), A′. Lo ricavo dalle ripetizioni della melodia e dalle conclusioni delle frasi.»", "partial": "«È un brano ripetitivo e allegro.»", "why": "È un’impressione generale: la griglia chiede elementi osservabili come frasi, ripetizioni e contrasti."}}, {"area": "Informatica", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Seguire l’esecuzione di una selezione condizionale", "features": "Traccia guidata, esempio e casi di confine", "evidence": "Spiega quale ramo viene eseguito per un input nuovo.", "case": {"probe": "if voto >= 6:\n    print(\"sufficiente\")\nelse:\n    print(\"insufficiente\")\nQuale ramo viene eseguito con voto = 6?", "full": "«Il primo: 6 >= 6 è vero, quindi stampa “sufficiente”. È proprio il caso di confine.»", "partial": "«Il secondo, perché 6 non è maggiore di 6.»", "why": "Legge >= come >: è l’errore tipico sui casi di confine, che la traccia guidata doveva far emergere."}}, {"area": "Diritto ed economia", "kind": "Lezione interattiva", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Riconoscere i requisiti essenziali del contratto: accordo, causa, oggetto, forma quando prescritta", "features": "Esempio annotato di compravendita, decisione su un caso, indizio e breve giustificazione", "evidence": "Individua il requisito mancante in un contratto nuovo descritto dal docente.", "case": {"probe": "Luca e Sara firmano un foglio: «Luca vende a Sara un veicolo». Non è indicato quale veicolo, né un criterio per individuarlo. Quale requisito manca?", "full": "«Manca un oggetto determinato o determinabile (art. 1346 c.c.): non si sa quale bene passi da Luca a Sara. L’accordo c’è, ma senza uno dei requisiti dell’art. 1325 il contratto è nullo.»", "partial": "«Manca la forma, perché il contratto è scritto male.»", "why": "Confonde la forma, richiesta solo in alcuni casi, con la completezza del contenuto: non applica i requisiti uno per uno."}}], "promptContrast": {"weak": "Crea una lezione interattiva.", "reason": "Non è specificato cosa deve fare lo studente né quale feedback riceverà."}, "schedule": "15 min · ripresa: che cosa ha funzionato nel quiz in classe o in simulazione · 30 min · dal contenuto all’attività: progettare feedback e indizi · 80 min · laboratorio: lezione interattiva in quattro passaggi · 10 min pausa · 35 min · revisione dei feedback tra colleghi di discipline diverse · 30 min · attività in classe (modalità A+B) · 10 min pausa · 30 min · test finale.", "classroom": {"mode": "A+B", "modeLabel": "Modalità A+B · La classe usa e poi valuta", "title": "Riscrivere un feedback che non aiuta", "intro": "Gli studenti seguono la lezione interattiva che hai verificato, poi diventano revisori del feedback. Così il vibe coding entra in classe come oggetto di analisi, non solo come strumento.", "steps": [["5 min · Previsione", "Mostra il primo esercizio e chiedi quale errore commetterebbe un compagno distratto."], ["10 min · Percorso", "Gli studenti completano i quattro passaggi annotando quale indizio li ha davvero aiutati."], ["10 min · Revisione", "Ogni gruppo sceglie un feedback poco utile e lo riscrive perché guidi il ragionamento senza dare la soluzione."], ["5 min · Confronto", "Raccogli le riscritture migliori: potrai usarle come nuovi requisiti nel prompt di revisione."]], "assess": "Valuta se il nuovo feedback individua il passaggio critico del ragionamento disciplinare."}}, {"title": "Costruire una simulazione guidata", "intro": "Progetta un’app che colleghi parametri e risultati. Esplicita il modello e le sue ipotesi, poi verifica formule, unità di misura e casi limite.", "product": "Un simulatore del moto uniforme con parametri, risultato e spiegazione.", "goals": ["Definire variabili, unità e intervalli validi.", "Separare modello matematico e interfaccia.", "Controllare risultati con calcoli indipendenti."], "example": {"kind": "Simulatore", "audience": "Studenti di seconda liceo", "goal": "Interpretare la relazione tra velocità, tempo e distanza nel moto uniforme", "features": "Velocità in m/s tra 0 e 30, tempo in secondi tra 0 e 120, distanza in metri, spiegazione della formula e validazione degli input"}, "steps": [{"title": "1. Esplicita il modello prima della grafica", "explain": "Nel moto uniforme con posizione iniziale zero usiamo s = v × t. Assumiamo velocità costante e consideriamo la distanza con velocità non negativa. Il modello non descrive accelerazioni.", "prompt": "Progetta una simulazione del moto uniforme per [destinatari]. Usa s = v × t, posizione iniziale zero, v non negativa e costante. Dichiara variabili, unità, ipotesi e limiti. Non scrivere ancora il codice.", "action": "Scrivi quali fenomeni il modello descrive e quali lascia fuori.", "check": "Non confondi una rappresentazione visiva con una validazione scientifica."}, {"title": "2. Definisci input e intervalli", "explain": "Un campo deve dichiarare unità e limiti. Un valore vuoto non equivale automaticamente a zero.", "prompt": "Prevedi v in m/s tra 0 e 30 e t in secondi tra 0 e 120. Consenti valori decimali. Rifiuta campi vuoti, testo e numeri fuori intervallo con un messaggio vicino al campo. Definisci quando aggiornare il risultato.", "action": "Prepara esempi validi e non validi per entrambi i parametri.", "check": "I limiti dell’interfaccia coincidono con quelli dichiarati nel modello."}, {"title": "3. Chiedi la prima applicazione", "explain": "Il risultato deve mostrare numero, unità e significato. Aggiungi un grafico solo se serve a comprendere la relazione.", "prompt": "Genera un unico file HTML con CSS e JavaScript per la specifica concordata. Mostra input etichettati, distanza in metri e sostituzione numerica nella formula. Non visualizzare un risultato nuovo se gli input non sono validi. Inserisci una nota sui limiti del modello.", "action": "Apri il simulatore e modifica un solo parametro alla volta.", "check": "Capisci che cosa cambia e perché senza leggere il codice."}, {"title": "4. Confronta con un risultato indipendente", "explain": "Non usare l’IA come unica fonte di verifica del proprio codice. Calcola casi semplici a mano.", "prompt": "Prepara test per v=5 m/s e t=12 s (atteso 60 m), v=0 e t=12 (atteso 0 m), v=30 e t=120 (atteso 3600 m), un campo vuoto e v=-1. Per ogni caso specifica esito atteso e motivazione.", "action": "Esegui i cinque test e annota eventuali differenze.", "check": "Il simulatore calcola i casi validi e rifiuta quelli non ammessi."}, {"title": "5. Migliora la comprensione del fenomeno", "explain": "Un controllo interattivo deve aiutare a interpretare, non solo muovere un oggetto.", "prompt": "Aggiungi una domanda di previsione: a tempo costante, cosa succede alla distanza se raddoppio la velocità entro l’intervallo valido? Mostra la spiegazione dopo la scelta. Mantieni formule e validazione esistenti.", "action": "Confronta v=5 e v=10 con t=12 e spiega il rapporto.", "check": "Ottieni 60 m e 120 m e sai motivare il raddoppio."}], "quiz": [{"case": "Vuoi simulare il moto uniforme. Quale specifica va chiarita prima del codice?", "options": ["Solo il colore del veicolo.", "Solo il titolo.", "Formula, variabili, unità, ipotesi e limiti.", "Il numero di animazioni."], "correct": 2, "feedback": "Il modello determina il significato dei risultati e il campo di validità.", "hint": "Chiediti che cosa dà significato a un risultato numerico."}, {"case": "Il simulatore usa s=v×t con v=5 m/s e t=12 s. Quale distanza ti aspetti?", "options": ["17 m.", "2,4 m.", "120 m.", "60 m."], "correct": 3, "feedback": "La distanza è 5 × 12 = 60 metri.", "hint": "Scrivi la formula e controlla le unità prima di calcolare."}, {"case": "La velocità consentita è tra 0 e 30 m/s. Inserisci -1. Che cosa deve fare l’app?", "options": ["Segnalare il valore fuori intervallo senza produrre un nuovo risultato valido.", "Trasformarlo in 1 senza avviso.", "Accettarlo sempre perché è un numero.", "Usarlo come tempo."], "correct": 0, "feedback": "Il valore viola l’intervallo esplicitamente scelto per il modello.", "hint": "Confronta il dato inserito con gli intervalli dichiarati."}, {"case": "Lasci vuoto il tempo. Il codice lo converte in zero senza avviso. Quale correzione chiedi?", "options": ["Nascondere il campo.", "Distinguere campo vuoto da zero e chiedere un valore.", "Mostrare sempre la distanza precedente come nuova.", "Sostituire il tempo con la velocità."], "correct": 1, "feedback": "Il dato mancante va gestito come tale; zero può invece essere un valore valido.", "hint": "Distingui un’informazione mancante da un valore numerico valido."}, {"case": "Per il modello dichiarato, v=0 e t=12. Quale risultato è coerente?", "options": ["12 m.", "Non definito perché si divide per zero.", "0 m.", "30 m."], "correct": 2, "feedback": "La formula è un prodotto: 0 × 12 = 0 metri.", "hint": "Sostituisci i due valori nella formula, senza trasformare il prodotto in una divisione."}, {"case": "Il simulatore mostra «60» senza unità. Che cosa chiedi?", "options": ["Solo un carattere più grande.", "Una transizione più veloce.", "Un nome diverso al pulsante.", "Distanza in metri e sostituzione numerica nella formula."], "correct": 3, "feedback": "Unità e calcolo esplicito aiutano a interpretare il risultato e a verificarlo.", "hint": "Chiediti quali informazioni servono per interpretare un numero."}, {"case": "L’animazione è fluida, ma non hai controllato i risultati numerici. Come valuti l’app?", "options": ["La grafica non basta: confronti casi noti e ipotesi del modello.", "La fluidità prova la formula.", "Il titolo prova la correttezza.", "Non servono controlli con input diversi."], "correct": 0, "feedback": "La qualità della rappresentazione non dimostra la correttezza del modello implementato.", "hint": "Distingui una rappresentazione convincente da una verifica indipendente."}, {"case": "A t=12 s passi da v=5 a v=10 m/s. Quale coppia di risultati è coerente?", "options": ["60 m e 60 m.", "60 m e 120 m.", "12 m e 24 m.", "120 m e 60 m."], "correct": 1, "feedback": "A tempo costante, s=v×t è proporzionale alla velocità: 5×12=60 e 10×12=120.", "hint": "Calcola separatamente i due casi mantenendo costante il tempo."}, {"case": "Un utente vuole studiare un veicolo che accelera. Il simulatore assume velocità costante. Che cosa precisi?", "options": ["Che l’animazione copre ogni fenomeno reale.", "Che basta cambiare il colore del veicolo.", "Che occorre un modello diverso, con nuove ipotesi e verifiche.", "Che l’accelerazione equivale sempre alla velocità."], "correct": 2, "feedback": "Il modello del moto uniforme non rappresenta un’accelerazione non nulla.", "hint": "Confronta le ipotesi del modello con il nuovo fenomeno."}, {"case": "Ai limiti ammessi, v=30 m/s e t=120 s. Quale controllo è corretto?", "options": ["Atteso 150 m.", "Atteso 4 m.", "Il valore massimo non va testato.", "Atteso 3600 m, con entrambi i limiti accettati."], "correct": 3, "feedback": "30 × 120 = 3600 metri; un limite incluso deve essere accettato e calcolato correttamente.", "hint": "Controlla prima se gli estremi sono inclusi, poi esegui il calcolo."}], "id": 3, "version": 2, "concepts": [{"title": "Una simulazione rappresenta un modello", "text": "Un simulatore rende esplorabili relazioni dichiarate tra variabili. Formula, unità, intervalli e ipotesi devono essere visibili. Una bella animazione non dimostra che il modello descriva correttamente il fenomeno."}, {"title": "Prevedi, modifica, spiega", "text": "Prima di muovere un controllo fai formulare una previsione, poi cambia una sola variabile e chiedi una spiegazione del risultato. Il confronto tra previsione e osservazione dà valore didattico all’interazione."}, {"title": "Adatta il significato di scenario", "text": "In matematica e scienze puoi verificare risultati con calcoli noti. In un dialogo linguistico o in un caso storico, le conseguenze dipendono da regole e interpretazioni esplicitate: presentale come scelte di scenario, senza attribuire loro la certezza di una legge fisica."}], "disciplineExamples": [{"area": "Italiano", "kind": "Scenario decisionale", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Valutare l’effetto di connettivi diversi sulla coerenza di un paragrafo", "features": "Scelte tra connettivi, conseguenze testuali dichiarate e confronto fra versioni", "evidence": "Spiega come cambia il rapporto logico tra due frasi.", "case": {"probe": "«Ha studiato molto, ___ non ha superato la verifica». Confronta «quindi» ed «eppure».", "full": "«Eppure crea un rapporto di opposizione: il risultato contraddice ciò che ci si aspetterebbe. Quindi introdurrebbe una conseguenza e renderebbe la frase incoerente.»", "partial": "«Eppure suona meglio.»", "why": "La scelta è giusta, ma motivata dall’orecchio e non dal rapporto logico tra le due frasi."}}, {"area": "Storia e filosofia", "kind": "Scenario decisionale", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Confrontare due interpretazioni di una decisione storica usando le fonti fornite", "features": "Bivi con ipotesi esplicite, fonti e conseguenze presentate come scenari possibili", "evidence": "Argomenta quale fonte sostiene la tua scelta e quali limiti restano.", "case": {"probe": "Nello scenario scegli: «La decisione fu dettata soprattutto da ragioni economiche». Hai due fonti: il verbale della riunione in cui fu presa e un’intervista rilasciata vent’anni dopo da uno dei protagonisti.", "full": "«Il verbale sostiene meglio la scelta, perché registra le ragioni discusse in quel momento; l’intervista può risentire del senno di poi o del bisogno di difendersi. Limite: un verbale riporta ciò che si è detto, non tutte le motivazioni.»", "partial": "«L’intervista, perché lui c’era e lo spiega meglio.»", "why": "Valuta l’autorevolezza del testimone ma non la distanza nel tempo né lo scopo della fonte, e non indica alcun limite."}}, {"area": "Lingue straniere", "kind": "Scenario decisionale", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Scegliere un registro linguistico adatto all’interlocutore", "features": "Dialogo a bivi con battute predisposte, contesto e conseguenze comunicative", "evidence": "Motiva una scelta di registro e proponi un’alternativa.", "case": {"probe": "Scrivi al dirigente di una scuola straniera per avere informazioni su uno scambio. Scegli tra «Hi! Can you tell me about the exchange?» e «Dear Sir or Madam, I am writing to ask for information about the exchange programme».", "full": "«La seconda: l’interlocutore è sconosciuto e ha un ruolo istituzionale, quindi serve un registro formale, con formula d’apertura e forme complete. Un’alternativa ammissibile: “Dear Principal, I would like to ask…”.»", "partial": "«La seconda, perché è più lunga.»", "why": "La scelta è corretta, ma il criterio no: la lunghezza non decide il registro."}}, {"area": "Matematica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esplorare come coefficiente angolare e intercetta modificano una retta", "features": "Input di m e q, grafico di y=mx+q, intervalli e casi noti", "evidence": "Prevedi il cambiamento del grafico prima di muovere un parametro.", "case": {"probe": "Retta y = 2x + 1. Prevedi che cosa succede se porti m da 2 a −2, lasciando q = 1.", "full": "«Passa ancora per (0; 1), perché q non cambia, ma diventa decrescente con la stessa inclinazione: è la simmetrica rispetto all’asse y.»", "partial": "«La retta si sposta più in basso.»", "why": "Confonde l’effetto di m, che cambia l’inclinazione, con quello di q, che sposta la retta in verticale."}}, {"area": "Scienze e fisica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Interpretare la relazione tra velocità costante, tempo e distanza", "features": "s=v×t, unità, intervalli ammessi e confronto con casi noti", "evidence": "Prevedi l’effetto di una variazione e controlla le unità del risultato.", "case": {"probe": "Un’auto procede a 15 m/s costanti. Che cosa succede alla distanza percorsa se il tempo passa da 4 s a 8 s?", "full": "«Raddoppia, da 60 m a 120 m: con velocità costante la distanza è direttamente proporzionale al tempo (s = v × t; m/s × s = m).»", "partial": "«Diventa 120.»", "why": "Il numero è giusto, ma mancano unità di misura e relazione di proporzionalità: non c’è prova che sappia prevedere un caso diverso."}}, {"area": "Arte e musica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esplorare la relazione tra battiti al minuto e intervallo tra impulsi", "features": "Tempo in BPM, intervallo 60/BPM secondi, limiti positivi e spiegazione", "evidence": "Prevedi come cambia l’intervallo raddoppiando i BPM.", "case": {"probe": "Il metronomo passa da 80 a 160 BPM. Come cambia l’intervallo tra due impulsi?", "full": "«Si dimezza: da 60/80 = 0,75 s a 60/160 = 0,375 s. BPM e intervallo sono inversamente proporzionali.»", "partial": "«Raddoppia anche l’intervallo.»", "why": "Applica una proporzionalità diretta dove la relazione è inversa: più battiti al minuto significano impulsi più ravvicinati."}}, {"area": "Informatica", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Osservare l’evoluzione di una variabile in un ciclo semplice", "features": "Stato passo passo, condizione, limite iterazioni e arresto", "evidence": "Prevedi valore finale e numero di iterazioni prima dell’esecuzione.", "case": {"probe": "x = 1\nwhile x < 20:\n    x = x * 3\nPrevedi valore finale e numero di iterazioni.", "full": "«x vale 27 dopo 3 iterazioni (1 → 3 → 9 → 27): il ciclo si ferma quando la condizione 27 < 20 risulta falsa.»", "partial": "«x vale 9, perché 27 supera 20.»", "why": "Pensa che il ciclo impedisca di superare il limite: la condizione si controlla prima di ogni iterazione, non dopo."}}, {"area": "Diritto ed economia", "kind": "Simulatore", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esplorare come prezzo e quantità di equilibrio cambiano quando si sposta la domanda o l’offerta", "features": "Curve lineari con parametri dichiarati, una curva spostata per volta, ipotesi del modello visibili", "evidence": "Prevedi la direzione di prezzo e quantità prima di spostare una curva.", "case": {"probe": "Il reddito dei consumatori aumenta e il bene è un bene normale. Prevedi prezzo e quantità prima di spostare la curva.", "full": "«La domanda si sposta a destra: a parità di offerta crescono sia il prezzo sia la quantità di equilibrio. Vale nel modello, con le altre condizioni invariate.»", "partial": "«Il prezzo sale, quindi la gente compra meno.»", "why": "Confonde lo spostamento della curva di domanda con un movimento lungo la curva: in questo caso la quantità scambiata aumenta."}}], "promptContrast": {"weak": "Fai una simulazione realistica.", "reason": "Il modello, le variabili e i criteri di verifica sono lasciati impliciti."}, "schedule": "15 min · ripresa · 35 min · che cos’è un modello e quali ipotesi contiene · 80 min · laboratorio: simulazione o scenario della propria disciplina · 10 min pausa · 40 min · controllo dei risultati con calcoli o fonti indipendenti · 30 min · attività «prevedi, osserva, spiega» (modalità B) · 10 min pausa · 30 min · test finale.", "classroom": {"mode": "B", "modeLabel": "Modalità B · La classe verifica il modello", "title": "Prevedi, osserva, spiega e metti alla prova", "intro": "La simulazione diventa un oggetto da interrogare. Gli studenti confrontano le previsioni con il comportamento dell’app e controllano il modello con un calcolo o una fonte indipendente.", "steps": [["5 min · Previsione", "Prima di muovere un controllo ogni studente scrive che cosa succederà e perché."], ["10 min · Osservazione", "Le coppie cambiano una sola variabile per volta e registrano risultato e unità di misura o conseguenze dello scenario."], ["10 min · Controllo", "Ogni coppia verifica un risultato a mano o con una fonte e cerca un caso in cui il modello smette di valere."], ["5 min · Spiegazione", "Raccogli i limiti trovati: quali ipotesi del modello andrebbero dichiarate meglio?"]], "assess": "Valuta il confronto tra previsione e osservazione e la capacità di individuare i limiti del modello."}}, {"title": "Realizzare e correggere un sito web", "intro": "Costruisci un piccolo sito per un progetto scolastico. Definisci pagine, navigazione e contenuti, poi riproduci gli errori e chiedi correzioni circoscritte.", "product": "Un sito statico con tre pagine, navigazione coerente e registro dei test.", "goals": ["Scrivere una specifica di pagine e collegamenti.", "Descrivere un errore in modo riproducibile.", "Verificare navigazione, tastiera e dispositivi diversi."], "example": {"kind": "Sito web statico", "audience": "Visitatori di un progetto scolastico", "goal": "Trovare obiettivi, attività e risorse del progetto", "features": "Tre pagine: presentazione, attività e risorse; menu coerente, collegamenti relativi, layout mobile, nessun modulo che raccolga dati"}, "steps": [{"title": "1. Disegna la mappa del sito", "explain": "Un sito di tre pagine ha bisogno di collegamenti coerenti. Dai un nome ai file e definisci dove deve portare ogni voce di menu.", "prompt": "Progetta un sito statico per [progetto] rivolto a [pubblico]. Usa index.html, attivita.html e risorse.html nella stessa cartella. Definisci contenuto di ogni pagina, menu comune e tre compiti che un visitatore deve riuscire a svolgere. Non scrivere ancora codice.", "action": "Disegna le tre pagine e i collegamenti di andata e ritorno.", "check": "Da ogni pagina puoi raggiungere le altre due senza usare il tasto Indietro del browser."}, {"title": "2. Genera i file con vincoli espliciti", "explain": "Chiedi file distinti con nomi concordati. Un pulsante che promette di inviare messaggi richiede una funzione reale; in questa versione mantieni solo navigazione e contenuti statici.", "prompt": "Genera i tre file HTML concordati con CSS condiviso in stile.css. Usa collegamenti relativi e menu identico con pagina corrente evidenziata. Inserisci contenuti segnaposto riconoscibili, nessun dato personale o credenziale. Non simulare invii o salvataggi che non esistono. Spiega dove salvare i file.", "action": "Salva i quattro file nella stessa cartella e apri index.html.", "check": "I nomi nel menu corrispondono esattamente ai nomi dei file."}, {"title": "3. Prova come un visitatore", "explain": "Verifica ciò che una persona deve fare: raggiungere attività, tornare alla presentazione e aprire una risorsa. Prova anche senza mouse.", "prompt": "Prepara una checklist di collaudo per il sito: tutti i link interni da ogni pagina, risorse esterne, ordine di tabulazione, focus visibile, leggibilità a 390 pixel e titoli coerenti. Indica risultato atteso per ogni prova.", "action": "Segui tutti i collegamenti e annota pagina, azione ed esito.", "check": "Nessun contenuto essenziale richiede uno scorrimento orizzontale sul telefono."}, {"title": "4. Descrivi il difetto prima della correzione", "explain": "«Non funziona» non identifica una causa. Fornisci file, passaggi, risultato atteso e risultato osservato.", "prompt": "Nel file [nome], cliccando [link] dopo [passaggi] ottengo [osservato], mentre mi aspetto [atteso]. Ecco il codice pertinente: [codice]. Individua la causa e proponi la modifica minima. Non riscrivere il sito e non cambiare i nomi dei file senza necessità.", "action": "Introduci una correzione alla volta e ripeti la prova che falliva.", "check": "Il difetto è riproducibile prima e risolto dopo la modifica."}, {"title": "5. Ripeti i test e prepara la pubblicazione", "explain": "Una correzione al menu condiviso può influire su tutte le pagine. Per un sito statico puoi pianificare una pubblicazione su un hosting per file statici.", "prompt": "Elenca i test di regressione dopo la correzione. Verifica anche maiuscole e minuscole nei nomi e nei link. Descrivi una procedura di pubblicazione statica senza dichiararla eseguita. Elenca ciò che richiederebbe invece un servizio server.", "action": "Riprova il menu da tutte le pagine. Registra ciò che hai effettivamente controllato.", "check": "Distingui sito statico, funzione simulata e servizio operativo."}], "quiz": [{"case": "Devi creare un sito con presentazione, attività e risorse. Quale richiesta prepara bene lo sviluppo?", "options": ["Genera una pagina casuale.", "Definisci prima mappa, nomi dei file e compiti del visitatore.", "Aggiungi subito un database.", "Scegli soltanto tre immagini."], "correct": 1, "feedback": "La mappa permette di definire contenuti e navigazione prima di generare i file.", "hint": "Pensa a come un visitatore si sposterà tra i contenuti."}, {"case": "Il menu punta a Attivita.html, ma il file pubblicato si chiama attivita.html. Quale controllo è pertinente?", "options": ["Il numero di paragrafi.", "Il colore dello sfondo.", "La corrispondenza esatta, incluse maiuscole e minuscole, tra link e file.", "La velocità del mouse."], "correct": 2, "feedback": "Un hosting può distinguere maiuscole e minuscole: il collegamento deve corrispondere al file.", "hint": "Confronta carattere per carattere il percorso richiesto e il nome del file."}, {"case": "Un link non si apre. Quale segnalazione aiuta a correggerlo?", "options": ["Non va bene.", "Rendi il sito migliore.", "Cambia tutte le pagine.", "In risorse.html il link X apre un errore, mentre dovrebbe aprire attivita.html; ecco il codice."], "correct": 3, "feedback": "File, azione, atteso e osservato rendono il problema riproducibile.", "hint": "Una descrizione utile permette di ricreare lo stesso errore."}, {"case": "Hai corretto il menu in un sito di tre pagine. Quali prove ripeti?", "options": ["I collegamenti da tutte e tre le pagine.", "Solo l’apertura dell’editor.", "Solo il titolo della pagina iniziale.", "Nessuna, una correzione al menu non ha altri effetti."], "correct": 0, "feedback": "Un menu ripetuto può avere difetti in più file e richiede una verifica incrociata.", "hint": "Il componente modificato è presente in una sola pagina o in più pagine?"}, {"case": "Un pulsante «Invia» mostra «Messaggio inviato» ma non esiste un servizio di invio. Come procedi?", "options": ["Lo presenti come servizio operativo.", "Rimuovi la promessa o implementi e verifichi un servizio reale prima di dichiararlo funzionante.", "Cambi solo il colore del messaggio.", "Aggiungi una seconda conferma simulata."], "correct": 1, "feedback": "Un messaggio nell’interfaccia non dimostra l’esecuzione di un invio reale.", "hint": "Distingui un messaggio sullo schermo da un’operazione realmente eseguita."}, {"case": "Sul telefono il testo essenziale esce dallo schermo. Che cosa chiedi all’IA?", "options": ["Un logo più grande.", "Una password per accedere.", "Una correzione responsive e una prova a larghezza mobile.", "La rimozione di tutti i link."], "correct": 2, "feedback": "Il difetto va affrontato sul layout e verificato nella dimensione che lo riproduce.", "hint": "Riproduci il problema nella dimensione dello schermo interessata."}, {"case": "Vuoi controllare se il menu funziona senza mouse. Quale prova è adatta?", "options": ["Scorrere con la rotella soltanto.", "Guardare uno screenshot.", "Aprire solo il file CSS.", "Usare Tab e attivare i link controllando focus e ordine."], "correct": 3, "feedback": "Navigare da tastiera permette di verificare raggiungibilità e visibilità dei controlli.", "hint": "Chiediti come raggiungere e attivare un link senza puntatore."}, {"case": "Le pagine sono nella stessa cartella. Quale link è coerente per aprire le attività?", "options": ["./attivita.html", "C:\\Desktop\\attivita.html", "Un percorso del tuo computer come unico collegamento.", "Un link vuoto senza destinazione."], "correct": 0, "feedback": "Un percorso relativo alla cartella del sito rimane utilizzabile anche dopo la pubblicazione.", "hint": "Un collegamento pubblicabile deve funzionare anche fuori dal tuo computer."}, {"case": "Per correggere un solo collegamento l’IA propone di riscrivere tutto. Che cosa chiedi?", "options": ["Nuove funzioni estranee.", "La modifica minima e i test per verificarla.", "Di eliminare il menu.", "Di cambiare tutti i nomi dei file senza motivo."], "correct": 1, "feedback": "Una correzione circoscritta limita le modifiche e rende più semplice il collaudo.", "hint": "Valuta quale cambiamento è necessario per risolvere proprio quel difetto."}, {"case": "Vuoi aggiungere account e salvataggio condiviso a un sito statico. Quale affermazione è corretta?", "options": ["Basta scrivere «salvato» nella pagina.", "Il solo HTML garantisce un archivio privato per account.", "Serve progettare un servizio di autenticazione e persistenza adeguato.", "Ogni hosting statico crea automaticamente un database privato."], "correct": 2, "feedback": "Account e dati condivisi richiedono un’architettura e verifiche ulteriori rispetto ai soli file statici.", "hint": "Distingui la visualizzazione di file dalla gestione privata di utenti e dati."}], "id": 4, "version": 2, "concepts": [{"title": "Che cosa fa un sito statico", "text": "Le pagine descrivono contenuti, collegamenti e interazioni nel browser. Un archivio condiviso o un accesso per account richiedono servizi aggiuntivi. Un messaggio «inviato» sullo schermo non prova che una comunicazione sia stata recapitata."}, {"title": "Debugging come indagine", "text": "Riproduci il difetto, scrivi atteso e osservato, formula un’ipotesi e applica una modifica minima. Conserva la versione precedente. Ogni correzione è un’ipotesi da verificare con lo stesso caso che falliva."}, {"title": "L’accessibilità è parte del compito", "text": "Chi usa tastiera, telefono o ingrandimento deve poter svolgere l’attività essenziale. Etichette chiare e focus visibile si provano con azioni reali, oltre alla revisione del codice."}], "disciplineExamples": [{"area": "Italiano", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un percorso di lettura con testi originali o autorizzati", "features": "Tre pagine: percorso, attività e risorse; crediti e navigazione", "evidence": "Un compagno trova un testo e raggiunge la relativa attività senza aiuto.", "case": {"probe": "Chiedi a un compagno: «Trova il racconto sul tema del viaggio e apri l’attività di scrittura collegata».", "full": "Il compagno raggiunge il testo dal menu «Percorso», segue il collegamento all’attività nella stessa pagina e la apre senza chiedere aiuto né tornare alla home.", "partial": "Il compagno trova il racconto, ma chiede dove sia l’attività o la cerca tornando alla home.", "why": "Il contenuto c’è, ma il collegamento tra testo e attività non è evidente: è un difetto di navigazione da correggere, non un errore del compagno."}}, {"area": "Storia e filosofia", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un dossier di fonti su un tema circoscritto", "features": "Tre pagine: quesito, fonti, confronto; provenienza dei documenti", "evidence": "Trova la fonte pertinente e spiega come risponde al quesito.", "case": {"probe": "Quesito del dossier: «Quali erano le condizioni di lavoro nelle fabbriche di fine Ottocento?». Il dossier contiene un regolamento di fabbrica del 1890 e un capitolo di manuale del 2010.", "full": "Lo studente apre il regolamento e spiega che risponde al quesito perché fissa orari, multe e divieti dell’epoca; ne indica la provenienza riportata nella pagina «Fonti».", "partial": "Lo studente sceglie il manuale «perché spiega tutto» e non dice da dove viene.", "why": "Trova un testo sul tema, ma non valuta come risponde al quesito né distingue la fonte dalla ricostruzione storiografica."}}, {"area": "Lingue straniere", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un itinerario linguistico con istruzioni accessibili", "features": "Tre pagine: situazione, attività, risorse; testi B1 validati", "evidence": "Un compagno raggiunge l’attività seguendo le istruzioni nella lingua studiata.", "case": {"probe": "Istruzioni in inglese: «Go to Activities, choose “At the station” and complete task 2».", "full": "Il compagno arriva all’attività seguendo solo le istruzioni in lingua e, se richiesto, spiega che cosa ha cercato e dove.", "partial": "Il compagno ci arriva cliccando a caso o dopo aver chiesto la traduzione.", "why": "La pagina è stata trovata, ma non grazie alla comprensione delle istruzioni, che era l’obiettivo."}}, {"area": "Matematica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare una piccola raccolta di problemi per argomento", "features": "Tre pagine: argomenti, problemi e metodi; notazione leggibile", "evidence": "Trova il metodo pertinente a un problema nuovo.", "case": {"probe": "Problema nuovo: «Un rettangolo ha perimetro 30 cm e un lato di 6 cm: quanto misura l’altro?». Trova nel sito il metodo pertinente.", "full": "Lo studente apre la sezione su perimetri e aree, sceglie la formula inversa del perimetro e spiega perché: conosce il perimetro e un lato e cerca l’altro (9 cm).", "partial": "Lo studente apre la pagina delle aree «perché c’è un rettangolo».", "why": "Riconosce la figura, ma non le grandezze note e quella cercata, che sono ciò che decide il metodo."}}, {"area": "Scienze e fisica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Presentare un’esperienza di laboratorio riproducibile", "features": "Tre pagine: domanda, procedura e risultati dimostrativi etichettati", "evidence": "Un compagno ricostruisce la procedura e distingue dati reali da dimostrativi.", "case": {"probe": "Esperienza: misura del periodo di un pendolo. La pagina «Risultati» contiene valori in parte etichettati come dimostrativi.", "full": "Il compagno elenca i passaggi nell’ordine corretto con materiali e misure, e indica quali valori sono dati reali e quali dimostrativi grazie all’etichetta.", "partial": "Il compagno ricostruisce la procedura, ma presenta i valori dimostrativi come risultati dell’esperimento.", "why": "La distinzione tra dati reali e dimostrativi non è stata colta: forse l’etichetta non è abbastanza visibile, e va corretta."}}, {"area": "Arte e musica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Curare una piccola mostra o un percorso di ascolto commentato", "features": "Tre pagine: tema, opere o brani, commenti; crediti e diritti dei materiali", "evidence": "Un visitatore collega un’opera al tema e ne motiva la scelta.", "case": {"probe": "Mostra sul tema «il paesaggio»: chiedi a un visitatore di scegliere un’opera e motivarla.", "full": "Il visitatore sceglie «Viandante sul mare di nebbia» di Caspar David Friedrich e motiva: il paesaggio occupa quasi tutta la scena e la figura di spalle invita a guardarlo, come spiega il commento.", "partial": "Il visitatore sceglie un’opera «perché è bella» o «perché c’è la natura».", "why": "La scelta non è collegata al tema del percorso né agli elementi indicati nei commenti."}}, {"area": "Informatica", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Costruire una documentazione navigabile di un piccolo progetto", "features": "Tre pagine: obiettivo, uso e test; menu coerente", "evidence": "Un collega apre l’esempio e ripete una prova senza aiuto.", "case": {"probe": "Un collega apre la documentazione e deve ripetere il test «inserimento di un voto non valido».", "full": "Il collega trova il test nella pagina «Test», usa i dati indicati e ottiene il messaggio atteso, senza chiedere aiuto.", "partial": "Il collega trova la pagina ma chiede quale valore inserire, oppure ottiene un esito diverso e non sa se è un errore.", "why": "La documentazione è incompleta: mancano i dati di input o il risultato atteso."}}, {"area": "Diritto ed economia", "kind": "Sito web statico", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Organizzare un percorso sui principi fondamentali della Costituzione", "features": "Tre pagine: principi, articoli citati dal testo ufficiale, casi da analizzare; fonte di ogni articolo", "evidence": "Collega un caso nuovo all’articolo pertinente e motiva il collegamento.", "case": {"probe": "Caso: un’azienda paga una lavoratrice meno dei colleghi uomini che svolgono le stesse mansioni. A quale articolo lo colleghi?", "full": "«All’art. 3 Cost., che vieta distinzioni di sesso, e, se il percorso lo riporta, all’art. 37, che garantisce alla donna lavoratrice la stessa retribuzione a parità di lavoro.»", "partial": "«All’art. 1, perché l’Italia è fondata sul lavoro.»", "why": "Si aggancia al tema generico, il lavoro, invece che al principio violato, l’uguaglianza."}}], "promptContrast": {"weak": "Crea un sito moderno.", "reason": "Mancano mappa, compiti del visitatore e limiti delle funzioni."}, "schedule": "15 min · ripresa · 30 min · sito statico e debugging come indagine · 75 min · laboratorio: sito in tre pagine e correzione di un difetto · 10 min pausa · 40 min · prove da tastiera, smartphone e ingrandimento tra colleghi · 30 min · progettare la specifica con gli studenti (modalità C guidata) · 10 min pausa · 30 min · test finale.", "classroom": {"mode": "C guidata", "modeLabel": "Modalità C guidata · La classe specifica, il docente genera", "title": "La specifica come compito di scrittura", "intro": "Gli studenti progettano senza usare direttamente l’IA: scrivono la mappa e i requisiti di un piccolo sito. Tu generi il prototipo dal loro testo, lo mostri e la classe verifica se rispetta la specifica.", "steps": [["5 min · Compito", "Presenta l’argomento del sito e chi lo visiterà."], ["10 min · Specifica", "I gruppi scrivono mappa, contenuto di ogni pagina e due verifiche osservabili."], ["10 min · Generazione e prova", "Generi in diretta una versione dalla specifica di un gruppo; la classe controlla collegamenti, contenuti e uso da tastiera."], ["5 min · Revisione", "Che cosa mancava nella specifica? Ogni gruppo aggiunge un requisito che avrebbe evitato il difetto."]], "assess": "Valuta chiarezza, completezza e verificabilità della specifica: è una competenza di scrittura e di argomentazione."}}, {"title": "Costruire la tua applicazione passo passo", "intro": "Scegli un’app utile: generatore di esercizi, test, lezione o altro strumento. Riduci l’idea a una versione minima e guida ogni iterazione con requisiti e prove.", "product": "Un prototipo personale accompagnato da specifica, prompt e registro delle modifiche.", "goals": ["Scegliere una funzione principale utile e fattibile.", "Pianificare iterazioni verificabili.", "Usare le prove di un’altra persona per migliorare il prodotto."], "example": {"kind": "Generatore di esercizi", "audience": "Studenti di prima liceo", "goal": "Esercitare somme tra frazioni con denominatori positivi", "features": "Generazione di un esercizio alla volta con valori piccoli, input numeratore e denominatore, verifica per equivalenza, suggerimento e nuovo esercizio"}, "steps": [{"title": "1. Scegli il bisogno e delimita la versione minima", "explain": "Puoi scegliere un quiz, una lezione, un sito, un generatore o uno strumento diverso. Per il primo rilascio scegli una sola azione centrale.", "prompt": "Voglio creare [tipo di app] per [utenti], per aiutarli a [obiettivo]. Aiutami a definire un prototipo minimo con tre funzioni indispensabili, funzioni escluse e criteri di accettazione. Non aggiungere account o servizi esterni se non sono necessari.", "action": "Scrivi una frase che descriva l’utilità del prototipo e tre funzioni essenziali.", "check": "La prima versione è realizzabile e ha un esito osservabile."}, {"title": "2. Chiarisci le regole del dominio", "explain": "Nel generatore di frazioni non basta confrontare il testo scritto dall’utente: 2/4 e 1/2 sono equivalenti. Rendi esplicite queste regole.", "prompt": "Per il generatore di somme di frazioni usa numeri piccoli e denominatori positivi. Accetta risposte equivalenti tramite confronto dei prodotti incrociati. Rifiuta denominatore zero e input non numerici. Definisci cinque esempi con esito atteso prima del codice.", "action": "Sostituisci le regole dell’esempio con quelle della tua disciplina se scegli un’altra app.", "check": "Sai motivare ogni criterio di correttezza senza affidarti soltanto all’IA."}, {"title": "3. Procedi per versioni", "explain": "Non richiedere tutte le estensioni insieme. Prima verifica il flusso essenziale, poi aggiungi un solo miglioramento.", "prompt": "Realizza la versione 1 in un file HTML: genera un esercizio, accetta la risposta e mostra l’esito. Rimanda statistiche, livelli e account. Spiega come provarla. Non dichiarare eseguiti test non effettuati.", "action": "Prova il flusso completo con un esercizio noto.", "check": "L’azione principale funziona prima di aggiungere funzioni accessorie."}, {"title": "4. Chiedi un miglioramento preciso", "explain": "Dopo una prova puoi aggiungere indizi, un livello o un’esportazione. Collega ogni modifica a un problema osservato.", "prompt": "Durante la prova ho osservato [problema]. Aggiungi [una funzione] mantenendo invariati [comportamenti]. Indica i file modificati e i test da ripetere. Non estendere l’ambito ad altre funzioni.", "action": "Conserva la versione precedente e confronta gli esiti degli stessi test.", "check": "Puoi ricondurre ogni modifica a una necessità concreta."}, {"title": "5. Fai provare e prepara la consegna", "explain": "Una persona che non conosce il progetto può individuare ostacoli che tu non noti. Raccogli osservazioni su compiti reali, non soltanto gradimento.", "prompt": "Prepara una scheda per far provare il prototipo a un’altra persona: tre compiti, risultati attesi, spazio per osservato e problemi. Poi aiutami a ordinare le correzioni per impatto sull’obiettivo. Non inventare risultati del test.", "action": "Fai eseguire i compiti, correggi un ostacolo importante e allega prompt, file e registro dei test.", "check": "La consegna include limiti noti e prove reali, non solo una descrizione positiva."}], "quiz": [{"case": "Vuoi un’app che faccia quiz, chat, agenda e simulazioni. Come scegli il primo rilascio?", "options": ["Costruisci tutte le funzioni insieme.", "Parti dall’animazione più complessa.", "Isoli un bisogno e un flusso principale verificabile.", "Lasci che l’IA cambi obiettivo a ogni prompt."], "correct": 2, "feedback": "La versione minima concentra il lavoro su un’utilità concreta e verificabile.", "hint": "Cerca la parte dell’idea che produce un’utilità già verificabile."}, {"case": "Il generatore deve accettare frazioni equivalenti. Atteso 1/2, l’utente risponde 2/4. Quale esito è coerente?", "options": ["Errore perché i testi sono diversi.", "Errore perché il numeratore è maggiore di uno.", "Risposta sempre da ignorare.", "Risposta corretta per equivalenza."], "correct": 3, "feedback": "1×4 e 2×2 danno entrambi 4: le due frazioni rappresentano lo stesso valore.", "hint": "Confronta il valore rappresentato dalle due frazioni, non la loro scrittura."}, {"case": "Un utente inserisce denominatore zero. Quale regola deve avere l’app?", "options": ["Rifiutare la risposta e spiegare che il denominatore non può essere zero.", "Accettarla come zero.", "Considerarla sempre corretta.", "Sostituirla senza avviso con uno."], "correct": 0, "feedback": "Una frazione con denominatore zero non è ammessa e richiede un messaggio di validazione.", "hint": "Richiama la condizione di validità di una frazione."}, {"case": "Prima di generare gli esercizi vuoi chiarire la correttezza. Che cosa chiedi?", "options": ["Solo uno stile accattivante.", "Regole del dominio ed esempi con risultato atteso.", "Un aumento delle animazioni.", "Un cambio di nome all’app."], "correct": 1, "feedback": "Gli esempi verificabili aiutano a tradurre le regole in controlli corretti.", "hint": "Chiediti quali esempi permettono di verificare la logica della disciplina."}, {"case": "L’IA propone statistiche e livelli quando il controllo risposte non funziona. Quale priorità scegli?", "options": ["La classifica.", "Il tema grafico.", "Il flusso essenziale di generazione, risposta e verifica.", "L’esportazione dei colori."], "correct": 2, "feedback": "Le estensioni non compensano un difetto nell’azione principale del prodotto.", "hint": "Pensa a quale difetto impedisce l’azione principale dell’app."}, {"case": "Dopo una prova vuoi aggiungere un indizio. Quale prompt mantiene il controllo della versione?", "options": ["Cambia tutto.", "Aggiungi qualsiasi miglioramento.", "Elimina le regole precedenti.", "Aggiungi un indizio preservando verifica, equivalenza e nuovo esercizio."], "correct": 3, "feedback": "Una richiesta mirata nomina sia la nuova funzione sia i comportamenti da preservare.", "hint": "Nomina sia ciò che cambia sia ciò che deve restare invariato."}, {"case": "Un collega trova difficile iniziare. Quale feedback è più utile da raccogliere?", "options": ["Compito tentato, passaggi, ostacolo osservato e risultato atteso.", "Solo un voto estetico.", "Solo il modello del computer.", "Una dichiarazione generica che tutto è bello."], "correct": 0, "feedback": "L’osservazione di un compito permette di individuare un problema utilizzabile per la revisione.", "hint": "Distingui un giudizio estetico dall’osservazione di un compito."}, {"case": "Hai una versione funzionante e vuoi cambiarla. Come rendi il confronto più affidabile?", "options": ["Sovrascrivi tutto senza traccia.", "Conservi la versione precedente e ripeti gli stessi test.", "Cambi contemporaneamente tutti i dati dei test.", "Controlli soltanto il titolo nuovo."], "correct": 1, "feedback": "Versione precedente e prove comuni permettono di valutare gli effetti della modifica.", "hint": "Per confrontare due versioni serve un riferimento comune."}, {"case": "Il generatore dice «errato» per 3/6 quando l’atteso è 1/2. Che cosa manca?", "options": ["Un carattere più grande.", "Una foto decorativa.", "Una regola di confronto per equivalenza, con test 3×2=1×6.", "Una classifica."], "correct": 2, "feedback": "I prodotti incrociati valgono entrambi 6: il confronto delle sole stringhe non basta.", "hint": "Verifica se le due frazioni rappresentano lo stesso valore."}, {"case": "Devi consegnare il project work. Quale insieme di materiali è più completo?", "options": ["Solo un’immagine.", "Solo il prompt finale.", "Solo il numero di richieste inviate.", "File, obiettivo, prompt, test con esiti, modifiche e limiti noti."], "correct": 3, "feedback": "La documentazione permette di comprendere, riprovare e migliorare il prototipo.", "hint": "Chiediti che cosa consentirà a un’altra persona di riprovare il progetto."}], "id": 5, "version": 2, "concepts": [{"title": "Dal prototipo al progetto didattico", "text": "La versione minima realizza l’azione centrale del progetto. Una funzione si aggiunge quando risponde a un bisogno osservato. Scrivi ciò che resta fuori dall’ambito per evitare che ogni richiesta allarghi il lavoro."}, {"title": "Il contenuto disciplina la tecnologia", "text": "Le regole di verifica dipendono dalla disciplina: equivalenza tra frazioni, uso di un connettivo, attendibilità di una fonte. Dichiara esempi accettati, esempi non accettati e casi che richiedono valutazione umana."}, {"title": "Costruire è anche documentare", "text": "Conserva prompt iniziale, revisioni, versioni del file e test. Far spiegare una scelta o un errore rende osservabile il processo del corsista e, in seguito, quello degli studenti."}], "disciplineExamples": [{"area": "Italiano", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare l’uso di connettivi logici in frasi originali", "features": "Banca validata, completamento, suggerimento; alternative linguistiche ammissibili esplicitate", "evidence": "Motiva la scelta del connettivo e discuti un’alternativa plausibile.", "case": {"probe": "«Era stanco, ___ continuò a lavorare». Il generatore accetta «tuttavia». Motiva la scelta e discuti «eppure».", "full": "«Tuttavia esprime opposizione tra la stanchezza e il continuare; anche eppure è ammissibile con lo stesso valore. Perciò no: indicherebbe una conseguenza.»", "partial": "«Va bene solo tuttavia, perché è la risposta dell’app.»", "why": "Affida la correttezza all’app invece che al rapporto logico, ed esclude un’alternativa valida."}}, {"area": "Storia e filosofia", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Analizzare argomenti distinguendo premesse e conclusione", "features": "Casi originali controllati, campi per ricostruzione e criteri di revisione", "evidence": "Ricostruisci un argomento inedito con premesse e conclusione.", "case": {"probe": "«Chi legge molto amplia il proprio lessico. Giulia legge un libro a settimana. Quindi il suo lessico si sta ampliando». Ricostruisci l’argomento.", "full": "«Premesse: chi legge molto amplia il lessico; Giulia legge molto, un libro a settimana. Conclusione: il lessico di Giulia si sta ampliando, introdotta da “quindi”.»", "partial": "«Premessa: Giulia legge un libro a settimana. Conclusione: chi legge molto amplia il lessico.»", "why": "Scambia la premessa generale con la conclusione e non riconosce l’indicatore “quindi”."}}, {"area": "Lingue straniere", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Allenare lessico contestualizzato da una banca di esempi controllata", "features": "Frasi originali, indizi graduati e varianti accettate dichiarate", "evidence": "Usa una parola in una frase nuova pertinente.", "case": {"probe": "Usa «borrow» in una frase nuova.", "full": "«Can I borrow your dictionary until tomorrow?»: significato corretto (prendere in prestito) e contesto pertinente.", "partial": "«Can you borrow me your pen?»", "why": "Confonde borrow con lend: la frase è plausibile ma il significato è rovesciato, un errore tipico per chi pensa in italiano «prestare»."}}, {"area": "Matematica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare somme di frazioni accettando risposte equivalenti", "features": "Numeri piccoli, denominatori positivi e confronto per equivalenza", "evidence": "Risolvi e motiva un caso diverso da quelli del generatore.", "case": {"probe": "Calcola 1/6 + 1/3 e motiva.", "full": "«1/6 + 2/6 = 3/6 = 1/2. Le due forme sono equivalenti, quindi entrambe corrette.»", "partial": "«2/9.»", "why": "Somma numeratori e denominatori; inoltre il generatore deve accettare sia 3/6 sia 1/2, come stabilito nelle regole del dominio."}}, {"area": "Scienze e fisica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare conversioni tra unità con risultati indipendenti di controllo", "features": "Unità dichiarate, valori semplici e feedback dimensionale", "evidence": "Risolvi una conversione nuova mostrando il fattore usato.", "case": {"probe": "Converti 2,5 km in metri e 750 g in kilogrammi, mostrando il fattore usato.", "full": "«2,5 km × 1000 m/km = 2500 m; 750 g ÷ 1000 g/kg = 0,75 kg. Il fattore è 1000 in entrambi i casi, ma il verso dipende dall’unità di partenza.»", "partial": "«2500 m e 750 000 kg.»", "why": "Usa il fattore giusto nel verso sbagliato: manca il controllo dimensionale (passando a un’unità più grande il numero deve diminuire)."}}, {"area": "Arte e musica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare analisi di elementi formali con una banca controllata", "features": "Schede, indizi progressivi e rubrica per interpretazioni aperte", "evidence": "Motiva un’analisi usando elementi osservabili nel materiale.", "case": {"probe": "Scheda: «Notte stellata» di Vincent van Gogh (1889). Motiva un’analisi usando elementi osservabili.", "full": "«Le pennellate dense e curve creano un ritmo vorticoso nel cielo; il cipresso scuro in primo piano fa da asse verticale e contrasta con l’orizzontalità del paese.»", "partial": "«Il quadro esprime la follia del pittore.»", "why": "È un’interpretazione biografica non ancorata al dipinto: la rubrica chiede di partire da segno, colore e composizione."}}, {"area": "Informatica", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare tracce di algoritmi con casi controllati", "features": "Esempi brevi, input validi e risultati verificati indipendentemente", "evidence": "Individua un caso limite e spiega il risultato atteso.", "case": {"probe": "L’algoritmo cerca il massimo in una lista di numeri. Individua un caso limite e il risultato atteso.", "full": "«La lista vuota: non esiste un massimo e l’algoritmo deve segnalarlo invece di restituire 0. Un altro caso: tutti valori negativi, dove partire da max = 0 darebbe un risultato sbagliato.»", "partial": "«Una lista molto lunga.»", "why": "Indica un caso grande, non un caso limite che mette in crisi la logica dell’algoritmo."}}, {"area": "Diritto ed economia", "kind": "Generatore di esercizi", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Esercitare il calcolo e l’interpretazione della variazione percentuale di prezzi e redditi", "features": "Valori piccoli, arrotondamento dichiarato, segno della variazione e risultati verificati indipendentemente", "evidence": "Interpreta segno e ordine di grandezza di una variazione nuova.", "case": {"probe": "Un prezzo passa da 80 € a 60 €. Calcola e interpreta la variazione percentuale.", "full": "«(60 − 80) / 80 × 100 = −25%: il prezzo è diminuito di un quarto; il segno negativo indica una riduzione.»", "partial": "«−33%.»", "why": "Divide per il valore finale: la variazione percentuale si calcola sul valore iniziale."}}], "promptContrast": {"weak": "Aggiungi tante funzioni utili.", "reason": "Non sono indicati priorità, perimetro minimo e condizioni di correttezza."}, "schedule": "15 min · presentazione delle idee di project work · 20 min · scelta della versione minima e di ciò che resta fuori · 100 min · sviluppo assistito per iterazioni brevi · 10 min pausa · 40 min · revisione tra pari con registro dei test · 25 min · attività con studenti costruttori (modalità C) · 10 min pausa · 20 min · test finale.", "classroom": {"mode": "C", "modeLabel": "Modalità C · Gli studenti costruiscono", "title": "Coppie progettista e verificatore", "intro": "Con account istituzionali autorizzati, gli studenti dialogano con l’IA per costruire un piccolo strumento disciplinare. I ruoli separati rendono osservabili decisioni, prove e correzioni.", "steps": [["5 min · Obiettivo", "Ogni coppia scrive l’azione di apprendimento e la funzione minima dell’app."], ["10 min · Iterazione", "Il progettista scrive il prompt; il verificatore prepara prima tre test con risultato atteso."], ["10 min · Prova e correzione", "Si scambiano i ruoli dopo la prima versione: chi verifica descrive un difetto in modo riproducibile."], ["5 min · Registro", "Consegna di prompt, test e una decisione presa dalla coppia e non dall’IA."]], "assess": "Valuta il registro delle prove e la motivazione delle scelte; l’aspetto grafico dell’app non è un criterio."}}, {"title": "Validare, documentare e pianificare l’uso", "intro": "Controlla il tuo prodotto con criteri espliciti, correggi i difetti prioritari e prepara istruzioni comprensibili. Concludi con un piano di sperimentazione e il test finale del percorso.", "product": "Un prototipo documentato, un rapporto di verifica e un piano di utilizzo.", "goals": ["Distinguere difetti bloccanti e miglioramenti facoltativi.", "Documentare solo verifiche effettuate.", "Preparare una sperimentazione con evidenze osservabili."], "example": {"kind": "Revisione di un prototipo", "audience": "Utenti del prototipo realizzato", "goal": "Verificare che il prodotto sostenga l’obiettivo dichiarato e sia utilizzabile", "features": "Checklist di test, priorità dei difetti, scheda d’uso, limiti noti e piano di sperimentazione senza dati personali"}, "steps": [{"title": "1. Confronta risultato e obiettivo", "explain": "Un prototipo piacevole può non esercitare la competenza prevista. Usa la specifica iniziale come riferimento e controlla i comportamenti reali.", "prompt": "Rivedi questo prototipo rispetto a obiettivo [obiettivo], utenti [destinatari] e requisiti [elenco]. Prepara una matrice requisito, evidenza necessaria e prova. Distingui analisi del codice e comportamento verificato nel browser. Non inventare esiti.", "action": "Raccogli una prova per ogni requisito essenziale.", "check": "Ogni affermazione di funzionamento ha un’evidenza o è indicata come da verificare."}, {"title": "2. Ordina i difetti per impatto", "explain": "Un punteggio sbagliato può impedire l’obiettivo; un colore migliorabile può aspettare. Stabilisci priorità motivate.", "prompt": "Organizza questi rilievi [elenco] in bloccanti, importanti e facoltativi. Motiva la priorità in relazione a correttezza, compito principale, accessibilità e dati. Proponi la correzione minima per il primo difetto.", "action": "Correggi prima un problema che impedisce l’uso e ripeti le prove.", "check": "Non confondi la gravità del difetto con la facilità della correzione."}, {"title": "3. Esegui un test incrociato", "explain": "Fai usare la versione aggiornata a una persona senza guidarla a ogni click. Segna comportamenti osservati, non supposizioni.", "prompt": "Prepara tre compiti per un test con un’altra persona e una griglia con passaggi, risultato atteso, osservato e ostacoli. Includi un errore dell’utente e una ripresa dell’attività. Non inserire nomi reali nella griglia dimostrativa.", "action": "Osserva l’uso, poi chiedi dove l’utente si è fermato e perché.", "check": "Il rapporto distingue ciò che è stato osservato dalle interpretazioni."}, {"title": "4. Scrivi una scheda d’uso e i limiti", "explain": "Una buona documentazione permette di iniziare senza conoscere il progetto. Spiega apertura, azioni, riavvio, dati salvati e limiti.", "prompt": "Scrivi una scheda d’uso per [utenti] del prototipo [descrizione]. Includi obiettivo, come aprirlo, tre azioni iniziali, gestione degli errori, dati eventualmente salvati e dove, limiti noti e come segnalare un difetto. Non promettere funzioni non implementate.", "action": "Fai leggere la scheda a un’altra persona e chiedile di iniziare l’attività.", "check": "La scheda corrisponde alla versione effettivamente consegnata."}, {"title": "5. Pianifica la sperimentazione e chiudi il percorso", "explain": "Scegli un’attività breve e un’evidenza collegata all’obiettivo. Il gradimento non dimostra da solo l’apprendimento.", "prompt": "Proponi una sperimentazione breve per [obiettivo e destinatari]. Specifica attività, durata, evidenza osservabile, criteri di successo e alternativa in caso di problema tecnico. Raccogli solo dati necessari e descrivi ciò che resterà da verificare dopo la prova.", "action": "Prepara il piano e confronta il prodotto finale con il bisogno iniziale.", "check": "Sai spiegare come osserverai l’apprendimento e che cosa farai se l’app non è disponibile."}], "quiz": [{"case": "Il prodotto è gradevole ma non esercita l’obiettivo dichiarato. Quale valutazione è corretta?", "options": ["È completo perché piace.", "Va rivisto rispetto alla coerenza didattica e ai requisiti.", "Basta aggiungere un logo.", "L’obiettivo non conta più dopo lo sviluppo."], "correct": 1, "feedback": "La validazione parte dal bisogno e dall’obiettivo, non dall’aspetto grafico.", "hint": "Confronta ciò che il prodotto fa con ciò che dovrebbe far imparare."}, {"case": "Hai un punteggio errato e un colore migliorabile. Quale difetto affronti prima?", "options": ["Il colore, sempre.", "Quello più rapido senza valutarne l’impatto.", "Il punteggio che compromette la correttezza del compito.", "Nessuno dei due."], "correct": 2, "feedback": "La priorità dipende dall’impatto sull’uso e sull’obiettivo.", "hint": "Valuta l’effetto di ciascun difetto sul compito principale."}, {"case": "L’IA afferma di avere testato l’app ma non ha aperto il browser. Che cosa riporti?", "options": ["Tutti i test superati.", "Una certificazione completa.", "Solo una frase promozionale.", "Analisi proposta o del codice, separata dai test da eseguire realmente."], "correct": 3, "feedback": "Non vanno dichiarate prove di comportamento che non sono state effettuate.", "hint": "Distingui una valutazione del codice da una prova di esecuzione."}, {"case": "Vuoi capire se una persona usa il prototipo senza aiuto. Quale metodo scegli?", "options": ["Assegni compiti e osservi passaggi, risultati e ostacoli.", "Fai tu tutti i click.", "Mostri solo uno screenshot.", "Chiedi solo se il colore piace."], "correct": 0, "feedback": "Una prova di compiti reali fornisce evidenze di usabilità.", "hint": "Chiediti quale metodo raccoglie comportamenti reali dell’utente."}, {"case": "La scheda d’uso promette salvataggio cloud ma l’app salva solo nel browser. Come la correggi?", "options": ["Lasci la promessa.", "Descrivi il salvataggio locale e i suoi limiti reali.", "Aggiungi un’icona cloud senza servizio.", "Nascondi ogni informazione sui dati."], "correct": 1, "feedback": "La documentazione deve corrispondere all’implementazione effettiva.", "hint": "Confronta la promessa della scheda con il luogo in cui i dati sono conservati."}, {"case": "Dopo una correzione vuoi dichiarare il difetto risolto. Quale evidenza serve?", "options": ["Il nuovo nome del file.", "Il numero di righe cambiate.", "La ripetizione del caso che falliva e dei controlli collegati, con esiti.", "La sola rassicurazione dell’IA."], "correct": 2, "feedback": "Una correzione va verificata sul problema originario e sulle funzioni interessate.", "hint": "Una modifica al codice non dimostra da sola che il problema sia scomparso."}, {"case": "Vuoi valutare una prova in classe sull’equivalenza tra frazioni. Quale evidenza è più pertinente?", "options": ["Il numero di colori dell’app.", "Il tempo passato sul logo.", "Il solo gradimento degli studenti.", "La correttezza e la motivazione di risposte a casi coerenti con l’obiettivo."], "correct": 3, "feedback": "L’evidenza deve riguardare la competenza esercitata, non soltanto il gradimento.", "hint": "Scegli un’evidenza collegata alla competenza, non all’aspetto dell’app."}, {"case": "Durante la sperimentazione il servizio IA non è disponibile. Quale piano è più robusto?", "options": ["Una versione già salvata o un’attività alternativa con lo stesso obiettivo.", "Interrompere senza alternativa già prevista.", "Chiedere password altrui.", "Dichiarare completata l’attività senza svolgerla."], "correct": 0, "feedback": "Un piano alternativo permette di preservare l’obiettivo anche con un guasto tecnico.", "hint": "Pensa a come mantenere l’obiettivo anche senza il servizio online."}, {"case": "Un test incrociato rileva «l’utente clicca tre volte senza trovare Avanti». Che tipo di dato è?", "options": ["Una prova automatica di apprendimento.", "Un’osservazione di usabilità da distinguere dalla sua interpretazione.", "Una dimostrazione che tutto il progetto va eliminato.", "Un voto disciplinare definitivo."], "correct": 1, "feedback": "Il comportamento osservato aiuta a diagnosticare l’interfaccia ma non dimostra da solo la causa o l’apprendimento.", "hint": "Separa il comportamento osservato dalle conclusioni sulle sue cause."}, {"case": "Devi presentare il prodotto finale. Quale dichiarazione è più affidabile?", "options": ["Funziona sempre per chiunque.", "Non esistono più limiti.", "Queste funzioni sono state provate con questi casi; questi limiti restano aperti.", "L’IA garantisce tutti gli utilizzi futuri."], "correct": 2, "feedback": "Un resoconto delimitato e basato su prove rende verificabili risultati e limiti.", "hint": "Una dichiarazione affidabile deve indicare l’ambito delle prove."}], "id": 6, "version": 2, "concepts": [{"title": "Tre domande di validazione", "text": "Il prodotto funziona? Il contenuto è corretto? L’attività aiuta a raggiungere l’obiettivo? Sono verifiche diverse. Il test tecnico e il gradimento da soli non dimostrano apprendimento."}, {"title": "L’evidenza viene prima della promessa", "text": "Nel rapporto distingui prove eseguite, risultati osservati e verifiche ancora aperte. La revisione deve poter essere ripetuta da un collega sulla stessa versione del prodotto."}, {"title": "Dalla formazione alla tua classe", "text": "Prepara una prova breve, un indicatore collegato all’obiettivo e un’alternativa tecnica. Il quadro UNESCO per i docenti collega competenze di IA, pedagogia, responsabilità e autonomia professionale [2]. La scheda qui proposta è un’attività del corso, non una certificazione UNESCO."}], "disciplineExamples": [{"area": "Italiano", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare correttezza dei feedback e qualità delle argomentazioni richieste", "features": "Test tecnico e rubrica per motivazioni aperte, con revisione del docente", "evidence": "Confronta una risposta iniziale e una risposta finale su testi diversi.", "case": {"probe": "Prima dell’uso dell’app lo studente ha scritto, sul testo A: «L’autore dice che i social sono negativi». Dopo, sul testo B, diverso, scrive la sua analisi.", "full": "Sul testo B la risposta individua la tesi e gli argomenti e li collega; sul testo A si limitava a parafrasare. La rubrica registra un passaggio di livello nel criterio «struttura».", "partial": "«La risposta finale è più lunga e più ordinata.»", "why": "Lunghezza e ordine non sono criteri della rubrica: servono testi diversi e un criterio esplicito."}}, {"area": "Storia e filosofia", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare provenienza delle fonti e pluralità delle interpretazioni", "features": "Verifica dei link, contestualizzazione e rubrica argomentativa", "evidence": "Sostieni una lettura con una fonte e formula un’obiezione.", "case": {"probe": "Lettura proposta: «Il Risorgimento fu soprattutto opera delle élite». Sostienila con una fonte e formula un’obiezione.", "full": "«La sostengo con i dati elettorali del 1861: votava circa il 2% della popolazione. Obiezione: la partecipazione di volontari di origine popolare alla spedizione dei Mille.»", "partial": "«È vero, perché lo dice il manuale.»", "why": "Sostituisce la fonte con un’autorità e non formula alcuna obiezione."}}, {"area": "Lingue straniere", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare livello, naturalezza e correttezza del feedback linguistico", "features": "Casi attesi, alternative corrette e revisione umana delle produzioni aperte", "evidence": "Confronta produzioni iniziali e finali con una rubrica di appropriatezza.", "case": {"probe": "Produzione iniziale e finale: un’email di scuse per una risposta in ritardo.", "full": "Iniziale: «Sorry, I am late». Finale: «I’m sorry I couldn’t reply sooner — I was away until Monday». Con la rubrica di appropriatezza si vede il progresso: motivazione esplicita e registro adatto al destinatario.", "partial": "«La finale non ha errori di grammatica, quindi è migliorata.»", "why": "La correttezza grammaticale è un solo criterio: la rubrica chiede l’adeguatezza al contesto comunicativo."}}, {"area": "Matematica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare formule, casi limite e spiegazioni matematiche", "features": "Risultati calcolati indipendentemente e input non ammessi", "evidence": "Individua un errore in una soluzione e giustifica la correzione.", "case": {"probe": "Soluzione da controllare: «(x + 3)² = x² + 9».", "full": "«Manca il doppio prodotto: (x + 3)² = x² + 6x + 9. Verifica con x = 1: 16 contro 10.»", "partial": "«È sbagliata, il risultato è diverso.»", "why": "Individua l’errore ma non dice dove sia né giustifica la correzione."}}, {"area": "Scienze e fisica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare modelli, unità e limiti delle conclusioni", "features": "Casi di riferimento e distinzione tra dato e interpretazione", "evidence": "Spiega che cosa il modello può e non può sostenere.", "case": {"probe": "Il simulatore dice che un’auto a 30 m/s percorre 1080 km in 10 ore. Che cosa può sostenere il modello?", "full": "«Il calcolo è coerente con s = v × t, ma il modello assume velocità costante per 10 ore: non può prevedere un viaggio reale con soste e accelerazioni.»", "partial": "«Il risultato è giusto, quindi il simulatore descrive bene il viaggio.»", "why": "Confonde la correttezza del calcolo con la validità del modello rispetto al fenomeno reale."}}, {"area": "Arte e musica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Controllare attribuzioni, crediti e qualità dei criteri di analisi", "features": "Verifica dei materiali e revisione umana delle interpretazioni", "evidence": "Confronta due analisi rispetto a una griglia esplicita.", "case": {"probe": "Due analisi dello stesso paesaggio: A «Mi trasmette calma»; B «La composizione orizzontale e i colori freddi poco saturi creano un’atmosfera calma». Confrontale con la griglia.", "full": "«B è più forte rispetto alla griglia (composizione, colore, luce): collega l’effetto a elementi osservabili. A esprime un’impressione legittima ma non verificabile.»", "partial": "«B è migliore perché usa parole tecniche.»", "why": "Il lessico specialistico non basta: conta il legame tra elemento osservabile ed effetto."}}, {"area": "Informatica", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare comportamento, accessibilità e dati di un’app", "features": "Test riproducibili e documentazione delle funzioni effettive", "evidence": "Riproduci un difetto e giustifica la modifica minima.", "case": {"probe": "Segnalazione ricevuta: «Il quiz a volte dà un punteggio sbagliato».", "full": "Riproduce il difetto con passaggi precisi (errata la 1, corretta la 2, riavvio, corretta la 1: punteggio 2 invece di 1), individua che il riavvio non azzera il punteggio e propone di azzerarlo solo nella funzione di riavvio.", "partial": "Fa riscrivere tutta l’app all’IA e il difetto non compare più.", "why": "Senza riproduzione non si sa se il difetto è risolto o solo nascosto, e la modifica non è minima."}}, {"area": "Diritto ed economia", "kind": "Revisione di un prototipo", "audience": "Studenti di liceo: specifica classe e prerequisiti", "goal": "Verificare correttezza e aggiornamento dei riferimenti normativi di un’app", "features": "Controllo degli articoli sul testo vigente in Normattiva, data di consultazione, distinzione tra norma e commento", "evidence": "Individua un riferimento superato e indica la fonte ufficiale corretta.", "case": {"probe": "L’app indica l’art. 18 dello Statuto dei lavoratori come tutela per tutti i licenziamenti illegittimi.", "full": "«Su Normattiva verifico che l’art. 18 è stato modificato dalla L. 92/2012 e che per gli assunti dal 7 marzo 2015 si applica il D.Lgs. 23/2015. Segnalo il riferimento come superato e indico il testo vigente con la data di consultazione.»", "partial": "«Il riferimento è giusto perché l’art. 18 esiste ancora.»", "why": "Che un articolo esista non significa che il contenuto citato sia ancora vigente: servono il testo aggiornato e la data di consultazione."}}], "promptContrast": {"weak": "Dimmi se va tutto bene.", "reason": "Non sono dichiarati requisiti, prove eseguite e limiti da verificare."}, "schedule": "20 min · rapporto di verifica: funziona, è corretto, aiuta ad apprendere? · 70 min · test incrociati e correzione dei difetti bloccanti · 10 min pausa · 40 min · scheda d’uso per gli studenti e piano di sperimentazione · 40 min · presentazione dei prototipi ai colleghi · 10 min pausa · 30 min · test finale e restituzione del percorso · 20 min · questionario e prossimi passi.", "classroom": {"mode": "B", "modeLabel": "Modalità B · La classe collauda e documenta", "title": "Gli studenti come collaudatori", "intro": "Prima dell’uso esteso, una classe pilota prova l’app con una checklist. Le osservazioni degli studenti diventano evidenze per il rapporto di verifica e per il piano di sperimentazione.", "steps": [["5 min · Consegna", "Distribuisci una checklist breve: funziona, è chiaro, mi ha aiutato a capire?"], ["10 min · Collaudo", "Gli studenti usano l’app su dispositivi diversi e segnalano ogni difetto con passaggi riproducibili."], ["10 min · Prova di apprendimento", "Proponi un caso nuovo senza l’app e confronta le risposte con l’obiettivo."], ["5 min · Sintesi", "Ordina le segnalazioni in bloccanti e migliorative e decidi che cosa correggere."]], "assess": "Tieni separati esito tecnico, gradimento e prova di apprendimento: sono tre evidenze diverse."}}];
